// GPS coordinates are used locally to suggest the nearest reference point, never stored or sent.
const locationState={id:'',busy:false,message:''};
const qcSorted=[...QC_MUNICIPALITIES].sort((a,b)=>a.name.localeCompare(b.name,'fr')||a.id.localeCompare(b.id));
let searchMap=null;
function selectedMunicipality(){return qcSorted.find(m=>m.id===locationState.id)}
function cityControls(){return `<label for="filter-municipality">${tr('Ville de départ','Starting city')}</label><input id="filter-municipality" list="municipality-choices" autocomplete="off" placeholder="${tr('Faire un choix — tapez une ville','Choose — type a city')}" value="${selectedMunicipality()?esc(municipalityLabel(selectedMunicipality())):''}"><datalist id="municipality-choices">${qcSorted.map(m=>`<option value="${esc(municipalityLabel(m))}"></option>`).join('')}</datalist><button class="secondary locate-button" data-action="locate" ${locationState.busy?'disabled':''}>⌖ ${locationState.busy?tr('Localisation…','Locating…'):tr('Me localiser','Locate me')}</button><small>${tr('Avec votre permission. Votre position précise n’est ni conservée ni envoyée.','With your permission. Your precise location is neither stored nor sent.')}</small><p class="location-status" role="status">${esc(locationState.message)}</p>`}
function mapPanel(){requestAnimationFrame(drawSearchMap);const m=selectedMunicipality();return `<section class="panel map-panel"><div class="row"><h2>${tr('Ma zone de recherche','My search area')}</h2><strong>${m?esc(m.name)+' · '+state.radius+' km':''}</strong></div>${m?`<div id="search-map" role="region" aria-label="${esc(tr('Carte de la zone de recherche','Search area map'))}"></div><p class="muted">${tr('Rayon à vol d’oiseau autour du point de référence de la municipalité. Les annonces restent fictives.','Straight-line radius around the municipality’s reference point. Listings remain fictional.')}</p><p id="map-error" role="status"></p>`:`<div class="map-placeholder">⌖<p>${tr('Choisissez une municipalité ou cliquez sur « Me localiser » pour afficher votre zone.','Choose a municipality or select “Locate me” to display your area.')}</p></div>`}<details><summary>${tr('Sources et carte','Sources and map')}</summary><p><a href="https://www.quebec.ca/gouvernement/portrait-quebec/repertoire-municipalites" target="_blank" rel="noopener">Répertoire des municipalités — Gouvernement du Québec</a> · 4 novembre 2026. <a href="https://statistique.quebec.ca/statistiques/divisions-territoriales/fichiers_code_geo/code-geographique-quebec.html" target="_blank" rel="noopener">ISQ : points de référence</a> · 31 août 2026.</p><p>${tr('Le fond de carte est chargé depuis Esri. Seule la zone de la ville choisie sert à le charger, pas votre position GPS précise. La suggestion automatique utilise le point municipal le plus proche : vérifiez la ville proposée.','Map tiles are loaded from Esri using the selected city area, not your precise GPS location. Automatic suggestions use the nearest municipal reference point: check the suggested city.')}</p></details></section>`}
function disposeSearchMap(){if(searchMap){searchMap.remove();searchMap=null}}
function drawSearchMap(){const el=document.getElementById('search-map'),m=selectedMunicipality();if(!el||!m||searchMap)return;if(!window.L){el.textContent=tr('Carte indisponible. La ville et le rayon restent sélectionnés.','Map unavailable. City and radius remain selected.');return}searchMap=L.map(el,{scrollWheelZoom:false}).setView(m.point,9);L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}',{maxZoom:16,attribution:'Tiles &copy; <a href="https://www.arcgis.com/home/item.html?id=30e5fe3149c34df1ba922e6f5bbf808f">Esri</a> · Esri, HERE, Garmin, USGS, NRCan, GeoBase, &copy; OpenStreetMap contributors'}).on('tileerror',()=>{const e=document.getElementById('map-error');if(e)e.textContent=tr('Le fond de carte ne charge pas. Vérifiez votre connexion.','Map tiles could not load. Check your connection.')}).addTo(searchMap);const circle=L.circle(m.point,{radius:state.radius*1000,color:'#6846da',weight:2,fillOpacity:.12}).addTo(searchMap);L.circleMarker(m.point,{radius:6,color:'#fff',weight:2,fillColor:'#6846da',fillOpacity:1}).addTo(searchMap).bindTooltip(m.name,{permanent:true,direction:'top'});searchMap.fitBounds(circle.getBounds(),{padding:[24,24]});L.control.scale({imperial:false}).addTo(searchMap)}
function municipalityDistance(a,b){const rad=x=>x*Math.PI/180,dlat=rad(b[0]-a[0]),dlon=rad(b[1]-a[1]);const h=Math.sin(dlat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
function locateMunicipality(){if(locationState.busy)return;if(!navigator.geolocation){locationState.message=tr('Localisation indisponible. Choisissez votre municipalité dans la liste.','Location unavailable. Choose your municipality from the list.');render();return}locationState.busy=true;locationState.message=tr('Autorisez la localisation dans la demande de votre navigateur.','Allow location access in your browser’s prompt.');render();navigator.geolocation.getCurrentPosition(pos=>{locationState.busy=false;const point=[pos.coords.latitude,pos.coords.longitude];let best=null,distance=Infinity;for(const m of qcSorted){const d=municipalityDistance(point,m.point);if(d<distance){best=m;distance=d}}if(distance>100||pos.coords.accuracy>25000){locationState.message=tr('Position trop éloignée ou imprécise. Choisissez votre municipalité manuellement.','Location too distant or inaccurate. Choose your municipality manually.')}else{locationState.id=best.id;state.city=best.name;locationState.message=tr('Municipalité suggérée : ','Suggested municipality: ')+best.name+tr('. Vérifiez ce choix; il est basé sur le point municipal le plus proche.','. Check this choice; it uses the nearest municipal reference point.')}render()},err=>{locationState.busy=false;locationState.message=err.code===1?tr('Permission refusée. Vous pouvez choisir votre municipalité manuellement.','Permission denied. You can choose your municipality manually.'):tr('Position introuvable. Réessayez ou choisissez une municipalité.','Location unavailable. Retry or choose a municipality.');render()},{enableHighAccuracy:false,timeout:12000,maximumAge:60000})}

function municipalityLabel(m){return m.name+' — '+m.region+' · '+m.type+' ('+m.id+')'}
